struct Point {
	var x: Double
	var y: Double

	func distance(to other: Point) -> Double {
		let dx = x - other.x
		let dy = y - other.y
		return (dx * dx + dy * dy).squareRoot()
	}

	mutating func translate(by delta: Point) {
		x += delta.x
		y += delta.y
	}
}

