func parseAge(_ s: String) throws -> Int {
	guard !s.isEmpty else { throw ParseError.emptyInput }
	guard let age = Int(s) else { throw ParseError.invalidFormat(s) }
	guard (0...150).contains(age) else { throw ParseError.outOfRange(age) }
	return age
}

class ListNode<T> {
	var val: T
	var next: ListNode<T>?
	init(_ val: T) { self.val = val }
}

class LinkedList<T> {
	private var head: ListNode<T>?

	func append(_ val: T) {
		let node = ListNode(val)
		guard let h = head else { head = node; return }
		var curr = h
		while let next = curr.next { curr = next }
		curr.next = node
	}

	var count: Int {
		var n = 0; var curr = head
		while curr != nil { n += 1; curr = curr?.next }
		return n
	}
}

class EventEmitter<T> {
	private var listeners: [(T) -> Void] = []

	func on(_ listener: @escaping (T) -> Void) {
		listeners.append(listener)
	}

	func emit(_ value: T) {
		listeners.forEach { $0(value) }
	}
}

