func compose<A, B, C>(
	_ f: @escaping (B) -> C,
	_ g: @escaping (A) -> B
) -> (A) -> C {
	return { f(g($0)) }
}

func memoize<T: Hashable, U>(_ fn: @escaping (T) -> U) -> (T) -> U {
	var cache: [T: U] = [:]
	return { input in
		if let cached = cache[input] { return cached }
		let result = fn(input)
		cache[input] = result
		return result
	}
}
